        margin: 0.75rem 0 0;
        color: var(--muted);
        max-width: 60ch;
        line-height: 1.6;
      }

      form.quiz {
        display: grid;
        gap: 1rem;
      }

      .form-field {
        background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01));
        border: 1px solid var(--border);
        border-radius: 1.25rem;
        box-shadow: var(--shadow);
        padding: 1.25rem;
      }

      fieldset {
        border: 0;
        margin: 0;
        padding: 0;
        min-inline-size: 0;
      }

      legend {
        font-size: 1.1rem;
        font-weight: 700;
        padding: 0;
        margin-bottom: 0.4rem;
      }

      .help-text {
        margin: 0 0 1rem;
        color: var(--muted);
        line-height: 1.5;
      }

      .choices {
        display: grid;
        gap: 0.75rem;
      }

      .choice {
        display: flex;
        align-items: flex-start;
        gap: 0.8rem;
        padding: 0.9rem 1rem;
        border: 1px solid var(--border);
        border-radius: 0.9rem;
        background: var(--panel-2);
        transition: border-color 0.15s ease, transform 0.15s ease, background-color 0.15s ease;
      }

      .choice:hover {
        border-color: var(--accent);
        transform: translateY(-1px);
      }

      .choice input {
        width: 1.1rem;
        height: 1.1rem;
        margin: 0.15rem 0 0;
        accent-color: var(--accent);
        flex: none;
      }

      .choice label {
        flex: 1;
        line-height: 1.45;
        color: var(--text);
        cursor: pointer;
      }

      .actions {
        display: flex;
        justify-content: flex-start;
        padding-top: 0.25rem;
      }

      button[type="submit"] {
        appearance: none;
