        button[type="submit"],
        a.skip-link {
          forced-color-adjust: auto;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#main">Skip to main content</a>
    <main id="main" class="page">
      <header class="hero">
        <h1>Computer Languages Quiz</h1>
        <p class="subtitle">Select all answers that apply for each question, then submit your quiz.</p>
      </header>

      <form class="quiz" id="quiz-form">
        <div id="quiz-root"></div>
        <div class="actions">
          <button type="submit">Submit quiz</button>
        </div>
        <p id="quiz-status" aria-live="polite" class="subtitle" style="margin-top:0.5rem;"></p>
      </form>
    </main>

    <script>
      const quizData = [
        {
          id: "question-1",
          prompt: "Which of these are programming languages?",
          helpText: "Choose every option that is a computer programming language.",
          choices: ["Python", "HTML", "JavaScript", "CSS"],
        },
        {
          id: "question-2",
          prompt: "Which languages are commonly used for web development?",
          choices: ["JavaScript", "Ruby", "COBOL", "TypeScript"],
        },
        {
          id: "question-3",
          prompt: "Which of these are compiled languages?",
          choices: ["Rust", "C", "Bash", "Go"],
        },
      ];

      const quizRoot = document.getElementById("quiz-root");

      function Question({ id, prompt, helpText, choices }) {
        const helpId = helpText ? `${id}-help` : "";
        const describedBy = helpText ? `aria-describedby="${helpId}"` : "";

        return `
          <div class="form-field">
            <fieldset ${describedBy}>
              <legend>${prompt}</legend>
              ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
              <div class="choices">
                ${choices
                  .map(
                    (choice, index) => `
                      <div class="choice">
                        <input
                          type="checkbox"
                          id="${id}-${index}"
                          name="${id}"
                          value="${choice}"
                        />
                        <label for="${id}-${index}">${choice}</label>
                      </div>
                    `
                  )
                  .join("")}
              </div>
            </fieldset>
          </div>
        `;
      }

      function Quiz({ questions }) {
        return questions.map(Question).join("");
      }

      quizRoot.innerHTML = Quiz({ questions: quizData });

      document.getElementById("quiz-form").addEventListener("submit", (event) => {
        event.preventDefault();
        const status = document.getElementById("quiz-status");
        status.textContent = "Quiz submitted. Your responses have been captured.";
      });
    </script>
  </body>
</html>
