         z-index: 1000;
       }

       a.skip-link:focus {
         transform: translateY(0);
         outline: 2px solid transparent;
       }

       .page {
         width: min(100%, 880px);
         margin: 0 auto;
         padding: 5rem 1.25rem 2rem;
       }

       .hero {
         margin-bottom: 1.5rem;
       }

       h1 {
         margin: 0;
         font-size: clamp(2rem, 4vw, 3.25rem);
         line-height: 1.1;
         letter-spacing: -0.04em;
       }

       .subtitle {
         margin: 0.75rem 0 0;
         color: var(--muted);
         max-width: 60ch;
         line-height: 1.6;
       }

       form.quiz {
         display: grid;
         gap: 1rem;
       }

       .form-field {
         background: linear-gradient(180deg, rgba(255, 255, 255, 0.03), rgba(255, 255, 255, 0.01));
         border: 1px solid var(--border);
         border-radius: 1.25rem;
         box-shadow: var(--shadow);
         padding: 1.25rem;
       }

       fieldset {
         border: 0;
         margin: 0;
         padding: 0;
         min-inline-size: 0;
       }

       legend {
         font-size: 1.1rem;
         font-weight: 700;
         padding: 0;
         margin-bottom: 0.4rem;
       }

       .help-text {
         margin: 0 0 1rem;
         color: var(--muted);
         line-height: 1.5;
       }

       .choices {
         display: grid;
         gap: 0.75rem;
       }

       .choice {
         display: flex;
         align-items: flex-start;
         gap: 0.8rem;
         padding: 0.9rem 1rem;
         border: 1px solid var(--border);
         border-radius: 0.9rem;
         background: var(--panel-2);
         transition: border-color 0.15s ease, transform 0.15s ease, background-color 0.15s ease;
       }

       .choice:hover {
         border-color: var(--accent);
         transform: translateY(-1px);
       }

       .choice input {
         width: 1.1rem;
         height: 1.1rem;
         margin: 0.15rem 0 0;
         accent-color: var(--accent);
         flex: none;
       }

       .choice label {
         flex: 1;
         line-height: 1.45;
         color: var(--text);
         cursor: pointer;
       }

       .actions {
         display: flex;
         justify-content: flex-start;
         padding-top: 0.25rem;
       }

       button[type="submit"] {
         appearance: none;
         border: 0;
         border-radius: 999px;
         padding: 0.9rem 1.4rem;
         font: inherit;
         font-weight: 700;
         color: #0b1020;
         background: linear-gradient(135deg, var(--accent-strong), var(--accent));
         cursor: pointer;
         box-shadow: 0 10px 24px rgba(124, 156, 255, 0.25);
       }

       button[type="submit"]:hover {
         filter: brightness(1.05);
       }

       button[type="submit"]:focus-visible,
       .choice input:focus-visible,
       .choice label:focus-visible,
       a.skip-link:focus-visible {
         outline: 3px solid var(--focus);
         outline-offset: 3px;
       }

       @media (max-width: 640px) {
         .page {
           padding-top: 4.25rem;
         }

         .form-field {
           padding: 1rem;
         }
       }

       @media (forced-colors: active) {
         :root {
           --bg: Canvas;
           --panel: Canvas;
           --panel-2: Canvas;
           --text: CanvasText;
           --muted: CanvasText;
           --border: ButtonBorder;
           --accent: Highlight;
           --accent-strong: Highlight;
           --focus: Highlight;
         }

         .choice,
         .form-field,
         button[type="submit"],
         a.skip-link {
           forced-color-adjust: auto;
         }
       }
     </style>
   </head>
   <body>
     <a class="skip-link" href="#main">Skip to main content</a>
     <main id="main" class="page">
       <header class="hero">
         <h1>Computer Languages Quiz</h1>
         <p class="subtitle">Select all answers that apply for each question, then submit your quiz.</p>
       </header>

       <form class="quiz" id="quiz-form">
         <div id="quiz-root"></div>
         <div class="actions">
           <button type="submit">Submit quiz</button>
         </div>
         <p id="quiz-status" aria-live="polite" class="subtitle" style="margin-top:0.5rem;"></p>
       </form>
     </main>

     <script>
       const quizData = [
         {
           id: "question-1",
           prompt: "Which of these are programming languages?",
           helpText: "Choose every option that is a computer programming language.",
           choices: ["Python", "HTML", "JavaScript", "CSS"],
         },
         {
           id: "question-2",
           prompt: "Which languages are commonly used for web development?",
           choices: ["JavaScript", "Ruby", "COBOL", "TypeScript"],
         },
         {
           id: "question-3",
           prompt: "Which of these are compiled languages?",
           choices: ["Rust", "C", "Bash", "Go"],
         },
       ];

       const quizRoot = document.getElementById("quiz-root");

       function Question({ id, prompt, helpText, choices }) {
         const helpId = helpText ? `${id}-help` : "";
         const describedBy = helpText ? `aria-describedby="${helpId}"` : "";

         return `
           <div class="form-field">
             <fieldset ${describedBy}>
               <legend>${prompt}</legend>
               ${helpText ? `<p class="help-text" id="${helpId}">${helpText}</p>` : ""}
               <div class="choices">
                 ${choices
                   .map(
                     (choice, index) => `
                       <div class="choice">
                         <input
                           type="checkbox"
                           id="${id}-${index}"
                           name="${id}"
                           value="${choice}"
                         />
                         <label for="${id}-${index}">${choice}</label>
                       </div>
                     `
                   )
                   .join("")}
               </div>
             </fieldset>
           </div>
         `;
       }

       function Quiz({ questions }) {
         return questions.map(Question).join("");
       }

       quizRoot.innerHTML = Quiz({ questions: quizData });

       document.getElementById("quiz-form").addEventListener("submit", (event) => {
         event.preventDefault();
         const status = document.getElementById("quiz-status");
         status.textContent = "Quiz submitted. Your responses have been captured.";
       });
     </script>
   </body>
 </html>

')
